/*
 Autor: Alex Rivera Tapia
 Tema: Creación de tablas y carga de datos - Flexi Zamora (PostgreSQL)
 Base: Scripts originales de creación y ampliación de datos

 INSTRUCCIONES DE EJECUCIÓN
 1. Crear una base de datos vacía, por ejemplo: FlexiZamoraPG.
 2. Conectarse a ESA base de datos en pgAdmin (Query Tool).
 3. Ejecutar este archivo completo UNA SOLA VEZ.

 IMPORTANTE:
 - PostgreSQL no cambia de base de datos con USE como SQL Server.
 - Este script crea las tablas y carga los datos dentro de la base
   a la que esté conectado el editor de consultas.
 - Se detiene si detecta tablas de Flexi ya existentes en public.
 - NO elimina ni reemplaza la base de datos ni sus registros.
 - Las contraseñas de los usuarios son marcadores de ejemplo;
   hay que activar un administrador desde Flexi Studio.
 - Los productos y marcas de demostración son ficticios.
 */

BEGIN;
SET LOCAL search_path TO public;

-- Protección: no ejecutar sobre una instalación existente de Flexi.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = 'public'
          AND table_name IN (
              'tipo_usuario', 'usuario', 'categoria', 'marca',
              'linea_estilo', 'estatus_producto', 'producto', 'talla',
              'inventario', 'forma_pago', 'venta', 'detalle_venta'
          )
    ) THEN
        RAISE EXCEPTION 'Ya existen tablas de Flexi en public. Use una base de datos vacía para evitar modificar la instalación actual.';
    END IF;
END
$$;

