-- ====================================================
-- MÓDULO 4: VENTAS Y TRANSACCIONES
-- ====================================================

-- 10. Crear tabla Forma_Pago
CREATE TABLE Forma_Pago (
    id_forma_pago SERIAL NOT NULL,
    descripcion_pago VARCHAR(30) NOT NULL,
    PRIMARY KEY (id_forma_pago)
);

-- 11. Crear tabla Venta
CREATE TABLE Venta (
    id_venta SERIAL NOT NULL,
    id_usuario INTEGER NOT NULL,
    id_forma_pago INTEGER NOT NULL,
    fecha_venta TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    monto_subtotal NUMERIC(10,2) NOT NULL,
    monto_iva NUMERIC(10,2) NOT NULL,
    monto_total NUMERIC(10,2) NOT NULL,
    PRIMARY KEY (id_venta),
    FOREIGN KEY (id_usuario) REFERENCES Usuario(id_usuario),
    FOREIGN KEY (id_forma_pago) REFERENCES Forma_Pago(id_forma_pago)
);

-- 12. Crear tabla Detalle_Venta
CREATE TABLE Detalle_Venta (
    id_detalle_venta SERIAL NOT NULL,
    id_venta INTEGER NOT NULL,
    id_inventario INTEGER NOT NULL,
    cantidad_vendida INTEGER NOT NULL CHECK(cantidad_vendida >= 1),
    precio_unitario_historico NUMERIC(10,2) NOT NULL,
    subtotal_linea NUMERIC(10,2) GENERATED ALWAYS AS (cantidad_vendida * precio_unitario_historico) STORED,
    PRIMARY KEY (id_detalle_venta),
    FOREIGN KEY (id_venta) REFERENCES Venta(id_venta),
    FOREIGN KEY (id_inventario) REFERENCES Inventario(id_inventario)
);

