-- ====================================================
-- VERIFICACIÓN FINAL: CANTIDAD DE REGISTROS POR TABLA
-- ====================================================
-- Resultado esperado en una base de datos vacía:
-- 12 tablas, 357 registros en total (incluye 5 roles).
-- La cifra de 352 corresponde a contar las otras 11 tablas.

SELECT tabla, registros
FROM (
    SELECT 1 AS orden, 'Tipo_Usuario' AS tabla, COUNT(*) AS registros FROM Tipo_Usuario
    UNION ALL SELECT 2, 'Usuario', COUNT(*) FROM Usuario
    UNION ALL SELECT 3, 'Categoria', COUNT(*) FROM Categoria
    UNION ALL SELECT 4, 'Marca', COUNT(*) FROM Marca
    UNION ALL SELECT 5, 'Linea_Estilo', COUNT(*) FROM Linea_Estilo
    UNION ALL SELECT 6, 'Estatus_Producto', COUNT(*) FROM Estatus_Producto
    UNION ALL SELECT 7, 'Producto', COUNT(*) FROM Producto
    UNION ALL SELECT 8, 'Talla', COUNT(*) FROM Talla
    UNION ALL SELECT 9, 'Inventario', COUNT(*) FROM Inventario
    UNION ALL SELECT 10, 'Forma_Pago', COUNT(*) FROM Forma_Pago
    UNION ALL SELECT 11, 'Venta', COUNT(*) FROM Venta
    UNION ALL SELECT 12, 'Detalle_Venta', COUNT(*) FROM Detalle_Venta
    UNION ALL SELECT 13, 'TOTAL', (
        (SELECT COUNT(*) FROM Tipo_Usuario) +
        (SELECT COUNT(*) FROM Usuario) +
        (SELECT COUNT(*) FROM Categoria) +
        (SELECT COUNT(*) FROM Marca) +
        (SELECT COUNT(*) FROM Linea_Estilo) +
        (SELECT COUNT(*) FROM Estatus_Producto) +
        (SELECT COUNT(*) FROM Producto) +
        (SELECT COUNT(*) FROM Talla) +
        (SELECT COUNT(*) FROM Inventario) +
        (SELECT COUNT(*) FROM Forma_Pago) +
        (SELECT COUNT(*) FROM Venta) +
        (SELECT COUNT(*) FROM Detalle_Venta)
    )
) AS verificacion
ORDER BY orden;
